from pathlib import Path


def rep(path, old, new):
    p=Path(path); s=p.read_text();
    if old not in s: raise SystemExit(f'PATCH_ANCHOR_MISSING:{path}:{old[:80]}')
    p.write_text(s.replace(old,new,1))

